  "headline": "FDA's shortage list shows hydrochlorothiazide shortage ongoing since 2023-01-19 with multiple manufacturers affected",
  "headline_cites": ["E13", "E10", "E11", "E12"],
  "sentences": [
    {
      "text": "FDA's shortage list shows hydrochlorothiazide has been in shortage since 2023-01-19, spanning 45 months as of 2026-10-21.",
      "cites": ["E13", "D7"]
    },
    {
      "text": "Aurobindo Pharma USA's quinapril/hydrochlorothiazide tablets remain current on the shortage list with discontinuation of manufacture cited as the reason.",
      "cites": ["E10"]
    },
    {
      "text": "Chartwell Molecular Holdings LLC's quinapril/hydrochlorothiazide tablets also remain current on the shortage list since 2023-01-19.",
      "cites": ["E11"]
    },
    {
      "text": "Teva Pharmaceuticals USA, Inc. has hydrochlorothiazide capsules listed as to be discontinued with a business decision to discontinue manufacture noted.",
      "cites": ["E12"]
    },
    {
      "text": "Current inventory across three Corvale sites ranges from 19 to 27 days on hand.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule-based best option is to buy from Alembic Pharmaceuticals Inc., which is not on FDA's shortage list today and whose plant Alembic Pharmaceuticals Limited had an NAI inspection on 2024-07-26.",
      "cites": ["D4"]
    },
    {
      "text": "Additional alternate manufacturers not on the shortage list include DirectRx (plant inspection NAI 2026-06-04) and Macleods Pharmaceuticals Limited (plant inspection VAI 2023-10-20).",
      "cites": ["D5", "D6"]
    }
  ]
}
